import json, csv, os
import numpy as np
from sklearn.cluster import KMeans
from sklearn.metrics import silhouette_score

OUT_DIR = "/root/autodl-tmp/trace-verdict-study-checkpoints/tier_clustering/"

# ── Data ──
DATA = {
    "Qwen-7B": {
        "exception_only": 0.9983, "ae_only": 0.9992, "vota": 0.9563,
        "nomarker": 0.9655, "loop_only": 0.8563, "label_only": 0.8622,
        "full_trace": 0.8176, "no_trace": 0.7513
    },
    "Qwen-1.5B": {
        "exception_only": 0.9983, "ae_only": 0.9908, "vota": 0.9958,
        "nomarker": 0.9780, "loop_only": 0.7832, "full_trace": 0.7706,
        "no_trace": 0.6731
    },
    "DeepSeek-6.7B": {
        "exception_only": 0.9933, "ae_only": 0.9874, "vota": 0.8445,
        "loop_only": 0.8126, "full_trace": 0.7916, "no_trace": 0.7336,
        "label_only": 0.2850
    },
    "CodeLlama-13B": {
        "exception_only": 0.9983, "ae_only": 0.9908, "vota": 0.9857,
        "loop_only": 0.7706, "no_trace": 0.7650
    },
}

PAPER_TIER1 = {"exception_only", "ae_only"}
PAPER_TIER2_LOW = {"loop_only", "full_trace", "no_trace"}
PAPER_MIDDLE = {"vota", "nomarker", "label_only"}


def compute_wcss(X, k, n_init=50, random_state=42):
    if k >= len(X):
        return None, None
    km = KMeans(n_clusters=k, n_init=n_init, random_state=random_state)
    km.fit(X)
    return km.inertia_, km.labels_


def gap_statistic(X, k_max=3, B=200, rng_seed=42):
    rng = np.random.RandomState(rng_seed)
    n = len(X)
    x_min, x_max = X.min(), X.max()

    results = {}
    for k in range(1, k_max + 1):
        if k >= n:
            break
        wcss_actual, _ = compute_wcss(X, k)
        log_wcss_refs = []
        for _ in range(B):
            X_ref = rng.uniform(x_min, x_max, size=(n, 1))
            wcss_ref, _ = compute_wcss(X_ref, k, n_init=10)
            if wcss_ref is not None and wcss_ref > 0:
                log_wcss_refs.append(np.log(wcss_ref))
        log_wcss_refs = np.array(log_wcss_refs)
        gap = log_wcss_refs.mean() - (np.log(wcss_actual) if wcss_actual > 0 else 0)
        sdk = log_wcss_refs.std() * np.sqrt(1 + 1.0 / B)
        results[k] = {"gap": float(gap), "sdk": float(sdk), "wcss": float(wcss_actual)}
    return results


def find_optimal_k(gap_results):
    ks = sorted(gap_results.keys())
    for i, k in enumerate(ks[:-1]):
        k_next = ks[i + 1]
        if gap_results[k]["gap"] >= gap_results[k_next]["gap"] - gap_results[k_next]["sdk"]:
            return k
    return ks[-1]


def analyze_model(model_name, conditions):
    names = list(conditions.keys())
    vals = np.array(list(conditions.values())).reshape(-1, 1)
    n = len(vals)

    result = {"model": model_name, "n_conditions": n, "conditions": conditions}

    # WCSS for k=1,2,3
    wcss_dict = {}
    labels_dict = {}
    for k in [1, 2, 3]:
        if k >= n:
            continue
        wcss, labels = compute_wcss(vals, k)
        wcss_dict[k] = float(wcss)
        if labels is not None:
            labels_dict[k] = {names[i]: int(labels[i]) for i in range(n)}
    result["wcss"] = wcss_dict

    # Gap statistic
    k_max = min(3, n - 1)
    gap_results = gap_statistic(vals, k_max=k_max)
    result["gap_statistic"] = {str(k): v for k, v in gap_results.items()}
    optimal_k = find_optimal_k(gap_results)
    result["optimal_k_gap"] = optimal_k

    # Silhouette
    sil = {}
    for k in [2, 3]:
        if k >= n and k > 2:
            continue
        if k >= n:
            continue
        _, labels = compute_wcss(vals, k)
        if labels is not None and len(set(labels)) > 1:
            sil[k] = float(silhouette_score(vals, labels))
    result["silhouette"] = sil

    # Cluster assignments for k=2
    if 2 in labels_dict:
        assignments = labels_dict[2]
        # Identify which cluster is "high" vs "low"
        cluster_means = {}
        for cond, cl in assignments.items():
            cluster_means.setdefault(cl, []).append(conditions[cond])
        cluster_means = {cl: np.mean(vs) for cl, vs in cluster_means.items()}
        high_cluster = max(cluster_means, key=cluster_means.get)
        low_cluster = min(cluster_means, key=cluster_means.get)

        tier_map = {}
        for cond, cl in assignments.items():
            tier_map[cond] = "Tier1_high" if cl == high_cluster else "Tier2_low"
        result["k2_tier_map"] = tier_map
        result["k2_cluster_means"] = {f"Tier1_high": float(cluster_means[high_cluster]),
                                       f"Tier2_low": float(cluster_means[low_cluster])}

        # Compare with paper tiers
        paper_match = True
        mismatches = []
        for cond, tier in tier_map.items():
            if cond in PAPER_TIER1 and tier != "Tier1_high":
                paper_match = False
                mismatches.append(f"{cond} expected Tier1 got {tier}")
            if cond in PAPER_TIER2_LOW and tier != "Tier2_low":
                paper_match = False
                mismatches.append(f"{cond} expected Tier2_low got {tier}")
        result["paper_tier_match"] = paper_match
        result["paper_tier_mismatches"] = mismatches

    # k=3 assignments
    if 3 in labels_dict:
        result["k3_assignments"] = labels_dict[3]

    return result


# ── Per-model analysis ──
all_results = {}
all_assignments = []
summary_lines = []

for model, conds in DATA.items():
    res = analyze_model(model, conds)
    all_results[model] = res

    for cond, val in conds.items():
        row = {"model": model, "condition": cond, "accuracy": val}
        if "k2_tier_map" in res:
            row["k2_cluster"] = res["k2_tier_map"].get(cond, "")
        if "k3_assignments" in res:
            row["k3_cluster"] = res["k3_assignments"].get(cond, "")
        all_assignments.append(row)

    # Summary
    summary_lines.append(f"\n{'='*60}")
    summary_lines.append(f"Model: {model} ({res['n_conditions']} conditions)")
    summary_lines.append(f"{'='*60}")
    summary_lines.append(f"WCSS: {res['wcss']}")
    summary_lines.append(f"Gap statistic: {json.dumps(res['gap_statistic'], indent=2)}")
    summary_lines.append(f"Optimal k (gap): {res['optimal_k_gap']}")
    summary_lines.append(f"Silhouette scores: {res['silhouette']}")
    if "k2_tier_map" in res:
        summary_lines.append(f"k=2 cluster means: {res['k2_cluster_means']}")
        summary_lines.append(f"k=2 assignments: {res['k2_tier_map']}")
        summary_lines.append(f"Paper tier match: {res['paper_tier_match']}")
        if res['paper_tier_mismatches']:
            summary_lines.append(f"Mismatches: {res['paper_tier_mismatches']}")

# ── Pooled analysis ──
summary_lines.append(f"\n{'='*60}")
summary_lines.append("POOLED ANALYSIS (all models × conditions)")
summary_lines.append(f"{'='*60}")

all_vals = []
all_labels_pool = []
for model, conds in DATA.items():
    for cond, val in conds.items():
        all_vals.append(val)
        all_labels_pool.append(f"{model}:{cond}")

X_pool = np.array(all_vals).reshape(-1, 1)
summary_lines.append(f"Total data points: {len(X_pool)}")

pool_gap = gap_statistic(X_pool, k_max=5)
pool_optimal_k = find_optimal_k(pool_gap)
summary_lines.append(f"Gap statistic (k=1..5): {json.dumps({str(k): v for k, v in pool_gap.items()}, indent=2)}")
summary_lines.append(f"Optimal k (gap): {pool_optimal_k}")

pool_sil = {}
for k in range(2, 6):
    if k >= len(X_pool):
        break
    _, labels = compute_wcss(X_pool, k)
    if labels is not None and len(set(labels)) > 1:
        pool_sil[k] = float(silhouette_score(X_pool, labels))
summary_lines.append(f"Silhouette scores: {pool_sil}")

# Pooled k=2 assignments
_, pool_labels_2 = compute_wcss(X_pool, 2)
cluster_contents = {}
for i, lbl in enumerate(pool_labels_2):
    cluster_contents.setdefault(int(lbl), []).append((all_labels_pool[i], all_vals[i]))
for cl in sorted(cluster_contents):
    members = sorted(cluster_contents[cl], key=lambda x: -x[1])
    mean_val = np.mean([v for _, v in members])
    summary_lines.append(f"\nPooled k=2, Cluster {cl} (mean={mean_val:.4f}, n={len(members)}):")
    for name, val in members:
        summary_lines.append(f"  {name}: {val:.4f}")

all_results["pooled"] = {
    "n_points": len(X_pool),
    "gap_statistic": {str(k): v for k, v in pool_gap.items()},
    "optimal_k_gap": pool_optimal_k,
    "silhouette": pool_sil,
}

# ── Special analyses ──
summary_lines.append(f"\n{'='*60}")
summary_lines.append("SPECIAL ANALYSES")
summary_lines.append(f"{'='*60}")

# CodeLlama loop_only vs no_trace
cl_loop = DATA["CodeLlama-13B"]["loop_only"]
cl_notrace = DATA["CodeLlama-13B"]["no_trace"]
summary_lines.append(f"\n1. CodeLlama loop_only ({cl_loop}) vs no_trace ({cl_notrace}): diff = {abs(cl_loop-cl_notrace):.4f}")
summary_lines.append(f"   These are only 0.56pp apart — clustering puts them in same cluster for all tested k.")

# DeepSeek label_only outlier
ds_label = DATA["DeepSeek-6.7B"]["label_only"]
ds_others = [v for k, v in DATA["DeepSeek-6.7B"].items() if k != "label_only"]
summary_lines.append(f"\n2. DeepSeek label_only = {ds_label}, next lowest = {min(ds_others):.4f}")
summary_lines.append(f"   Gap to next = {min(ds_others) - ds_label:.4f} — extreme outlier.")
# Check if k=3 separates it
if "k3_assignments" in all_results["DeepSeek-6.7B"]:
    ds_k3 = all_results["DeepSeek-6.7B"]["k3_assignments"]
    label_cluster = ds_k3["label_only"]
    alone = all(v != label_cluster for k, v in ds_k3.items() if k != "label_only")
    summary_lines.append(f"   k=3 cluster for label_only: {label_cluster}, alone in cluster: {alone}")

# Cross-model consistency
summary_lines.append(f"\n3. Cross-model k=2 consistency:")
conditions_all = set()
for conds in DATA.values():
    conditions_all.update(conds.keys())

for cond in sorted(conditions_all):
    tiers = []
    for model in DATA:
        if cond in DATA[model]:
            res = all_results[model]
            if "k2_tier_map" in res and cond in res["k2_tier_map"]:
                tiers.append(f"{model}={res['k2_tier_map'][cond]}")
    if tiers:
        summary_lines.append(f"   {cond}: {', '.join(tiers)}")

# ── Write outputs ──
with open(os.path.join(OUT_DIR, "tier_clustering_results.json"), "w") as f:
    json.dump(all_results, f, indent=2)

fieldnames = ["model", "condition", "accuracy", "k2_cluster", "k3_cluster"]
with open(os.path.join(OUT_DIR, "cluster_assignments.csv"), "w", newline="") as f:
    writer = csv.DictWriter(f, fieldnames=fieldnames, extrasaction="ignore")
    writer.writeheader()
    writer.writerows(all_assignments)

summary_text = "\n".join(summary_lines)
with open(os.path.join(OUT_DIR, "tier_clustering_summary.txt"), "w") as f:
    f.write(summary_text)

print(summary_text)
print(f"\n\nFiles written to {OUT_DIR}")
